import React, { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import { motion } from 'framer-motion';
import styles from './AdminPanel.module.css';

// ================= ПРЕМИАЛЬНЫЕ МАРКИ И МОДЕЛИ (расширенные) =================
const brandModels = {
  "BMW": [
    "1 Series", "2 Series Gran Coupe", "2 Series Coupe", "3 Series Sedan", "3 Series Touring",
    "4 Series Gran Coupe", "4 Series Coupe", "5 Series Sedan", "5 Series Touring",
    "6 Series Gran Coupe", "7 Series", "8 Series Gran Coupe", "8 Series Coupe",
    "X1", "X2", "X3", "X4", "X5", "X6", "X7", "XM",
    "M2 Coupe", "M3 Sedan", "M3 Touring", "M4 Coupe", "M5 Sedan", "M8 Gran Coupe",
    "Z4 Roadster", "i4 Gran Coupe", "i5 Sedan", "i7 Sedan", "iX SUV"
  ],
  "Mercedes-Benz": [
    "A-Class Hatchback", "A-Class Sedan", "B-Class", "C-Class Sedan", "C-Class Estate",
    "E-Class Sedan", "E-Class Estate", "S-Class Sedan", "S-Class Maybach",
    "CLA Coupe", "CLA Shooting Brake", "CLS Coupe", "GLA SUV", "GLB SUV",
    "GLC SUV", "GLC Coupe", "GLE SUV", "GLE Coupe", "GLS SUV",
    "G-Class SUV", "EQS Sedan", "EQS SUV", "EQE Sedan", "EQE SUV",
    "SL Roadster", "AMG GT Coupe", "AMG GT 4-Door Coupe"
  ],
  "Audi": [
    "A1 Sportback", "A3 Sportback", "A3 Sedan", "A4 Sedan", "A4 Avant",
    "A5 Sportback", "A5 Coupe", "A6 Sedan", "A6 Avant", "A7 Sportback",
    "A8 Sedan", "Q2", "Q3", "Q3 Sportback", "Q5", "Q5 Sportback",
    "Q7", "Q8", "e-tron", "e-tron Sportback", "e-tron GT", "R8 Coupe", "TT Coupe"
  ],
  "Porsche": [
    "718 Cayman", "718 Boxster", "911 Carrera", "911 Carrera S", "911 Turbo",
    "911 Turbo S", "911 GT3", "911 GT3 RS", "Taycan", "Taycan Cross Turismo",
    "Panamera", "Panamera Sport Turismo", "Cayenne", "Cayenne Coupe", "Macan"
  ],
  "Lexus": ["IS 300", "ES 250", "ES 350", "LS 500", "LC 500", "RC F", "UX 200", "NX 350", "RX 350", "RX 500h", "GX 460", "LX 600"],
  "Bentley": ["Bentayga", "Bentayga EWB", "Continental GT", "Continental GTC", "Flying Spur"],
  "Rolls-Royce": ["Ghost", "Ghost Extended", "Phantom", "Phantom Extended", "Cullinan", "Wraith", "Dawn"],
  "Lamborghini": ["Huracán EVO", "Huracán STO", "Aventador SVJ", "Urus", "Revuelto"],
  "Ferrari": ["Roma", "Portofino M", "SF90 Stradale", "296 GTB", "812 Superfast", "F8 Tributo"],
  "McLaren": ["GT", "720S", "765LT", "Artura"],
  "Land Rover": ["Range Rover", "Range Rover Sport", "Range Rover Velar", "Range Rover Evoque", "Discovery", "Discovery Sport", "Defender 90", "Defender 110"],
  "Jaguar": ["XE", "XF", "F-Type Coupe", "F-Type Convertible", "E-Pace", "F-Pace", "I-Pace"],
  "Maserati": ["Ghibli", "Quattroporte", "Levante", "MC20", "Grecale"],
  "Aston Martin": ["Vantage", "Vantage Roadster", "DB11", "DBX", "DBS Superleggera"],
  "Cadillac": ["CT4", "CT5", "Escalade", "XT5", "XT6"],
  "Infiniti": ["Q50", "Q60", "QX50", "QX55", "QX60", "QX80"],
  "Genesis": ["G70", "G80", "G90", "GV70", "GV80"],
  "Bugatti": ["Chiron", "Chiron Super Sport", "Divo", "Centodieci", "Mistral"],
  "Koenigsegg": ["Jesko", "Gemera", "Regera", "CC850"],
  "Pagani": ["Huayra", "Huayra BC", "Utopia", "Zonda R"],
  "Alfa Romeo": ["Giulia", "Giulia Quadrifoglio", "Stelvio", "Tonale"],
  "Lotus": ["Emira", "Evija", "Eletre"],
  "Rimac": ["Nevera"],
  "Polestar": ["Polestar 1", "Polestar 2", "Polestar 3", "Polestar 4"],
  "Lucid": ["Air", "Air Grand Touring", "Gravity"]
};

const bodyTypesRussian = {
  "sedan": "Седан",
  "coupe": "Купе",
  "cabriolet": "Кабриолет",
  "wagon": "Универсал",
  "suv": "Внедорожник",
  "pickup": "Пикап",
  "limousine": "Лимузин",
  "hatchback": "Хэтчбек",
};

// ================= КОМПОНЕНТ =================
const AdminPanel = () => {
  const { user } = useAuth();
  const [activeTab, setActiveTab] = useState('dashboard');
  const [stats, setStats] = useState(null);
  const [users, setUsers] = useState([]);
  const [cars, setCars] = useState([]);
  const [testDrives, setTestDrives] = useState([]);
  const [loading, setLoading] = useState(true);

  // ---------- Состояния формы ----------
  const [showAddForm, setShowAddForm] = useState(false);
  const [newCar, setNewCar] = useState({
    brand: '',
    model: '',
    year: '',
    price: '',
    description: '',
    image_url: '',
    body_type: 'sedan',
    restyling: false,   // чекбокс – булево
  });
  const [uploading, setUploading] = useState(false);
  const [addError, setAddError] = useState('');
  const [formErrors, setFormErrors] = useState({});

  // ---------- Управление изображениями ----------
  const [selectedCarId, setSelectedCarId] = useState(null);
  const [newImageUrl, setNewImageUrl] = useState('');
  const [carImages, setCarImages] = useState([]);

  // ================= ЗАГРУЗКА ДАННЫХ =================
  const fetchData = async () => {
    try {
      const [statsRes, usersRes, carsRes, tdRes] = await Promise.all([
        api.get('/admin/stats'),
        api.get('/admin/users'),
        api.get('/cars/'),
        api.get('/testdrives/all'),
      ]);
      setStats(statsRes.data);
      setUsers(usersRes.data);
      setCars(carsRes.data);
      setTestDrives(tdRes.data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchData(); }, []);

  // ================= ОБРАБОТЧИКИ МАРКИ/МОДЕЛИ =================
  const handleBrandChange = (e) => {
    const brand = e.target.value;
    setNewCar(prev => ({ ...prev, brand, model: '' }));
    setFormErrors(prev => ({ ...prev, brand: '', model: '' }));
  };

  const handleModelChange = (e) => {
    setNewCar(prev => ({ ...prev, model: e.target.value }));
    setFormErrors(prev => ({ ...prev, model: '' }));
  };

  // ================= ВАЛИДАЦИЯ =================
  const validateForm = () => {
    const errors = {};
    if (!newCar.brand) errors.brand = 'Выберите марку';
    if (!newCar.model) errors.model = 'Выберите модель';
    const year = parseInt(newCar.year);
    if (!newCar.year || isNaN(year) || year < 1900 || year > 2030) errors.year = 'Год должен быть 1900–2030';
    const price = parseFloat(newCar.price);
    if (!newCar.price || isNaN(price) || price <= 0) errors.price = 'Цена должна быть положительной';
    setFormErrors(errors);
    return Object.keys(errors).length === 0;
  };

  // ================= ЗАГРУЗКА ФАЙЛА =================
  const handleFileUpload = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    setUploading(true);
    const formData = new FormData();
    formData.append('file', file);
    try {
      const res = await api.post('/cars/upload_image', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      setNewCar(prev => ({ ...prev, image_url: res.data.image_url }));
    } catch (err) {
      alert('Ошибка загрузки файла');
    } finally {
      setUploading(false);
    }
  };

  // ================= ДОБАВЛЕНИЕ АВТОМОБИЛЯ =================
  const handleAddCar = async (e) => {
    e.preventDefault();
    if (!validateForm()) return;
    setAddError('');
    try {
      const carData = {
        brand: newCar.brand,
        model: newCar.model,
        year: parseInt(newCar.year),
        price: parseFloat(newCar.price),
        description: newCar.description,
        image_url: newCar.image_url,
        body_type: newCar.body_type,
        restyling: newCar.restyling,   // true/false
      };
      const res = await api.post('/cars/', carData);
      setCars(prev => [...prev, res.data]);
      setShowAddForm(false);
      setNewCar({
        brand: '', model: '', year: '', price: '',
        description: '', image_url: '', body_type: 'sedan', restyling: false,
      });
      setFormErrors({});
    } catch (err) {
      const detail = err.response?.data?.detail;
      if (Array.isArray(detail)) {
        setAddError(detail.map(e => e.msg).join('. '));
      } else if (typeof detail === 'string') {
        setAddError(detail);
      } else {
        setAddError('Ошибка сервера');
      }
    }
  };

  // ================= ОСТАЛЬНЫЕ ОБРАБОТЧИКИ =================
  const handleDeleteUser = async (userId) => {
    if (window.confirm('Удалить пользователя?')) {
      await api.delete(`/admin/users/${userId}`);
      setUsers(users.filter(u => u.id !== userId));
    }
  };

  const handleRoleChange = async (userId, newRole) => {
    await api.put(`/admin/users/${userId}/role`, { role: newRole });
    setUsers(users.map(u => u.id === userId ? { ...u, role: newRole } : u));
  };

  const handleDeleteCar = async (carId) => {
    if (window.confirm('Удалить автомобиль?')) {
      await api.delete(`/cars/${carId}`);
      setCars(cars.filter(c => c.id !== carId));
    }
  };

  // ---------- Галерея изображений ----------
  const openCarImages = (carId) => {
    setSelectedCarId(carId);
    const car = cars.find(c => c.id === carId);
    setCarImages(car?.images || []);
    setNewImageUrl('');
  };

  const handleAddImage = async () => {
    if (!newImageUrl.trim()) return;
    try {
      const res = await api.post(`/cars/${selectedCarId}/images`, { image_url: newImageUrl });
      setCarImages(prev => [...prev, res.data]);
      setNewImageUrl('');
    } catch (err) {
      alert('Ошибка добавления изображения');
    }
  };

  const handleDeleteImage = async (imageId) => {
    try {
      await api.delete(`/cars/images/${imageId}`);
      setCarImages(prev => prev.filter(img => img.id !== imageId));
    } catch (err) {
      alert('Ошибка удаления изображения');
    }
  };

  if (loading) return <div className={styles.loading}>Загрузка...</div>;

  const availableModels = newCar.brand ? (brandModels[newCar.brand] || []) : [];

  return (
    <motion.div className={styles.container} initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      <h2 className={styles.title}>Админ-панель</h2>
      <div className={styles.tabs}>
        {['dashboard', 'users', 'cars', 'testdrives'].map(tab => (
          <button
            key={tab}
            className={`${styles.tab} ${activeTab === tab ? styles.active : ''}`}
            onClick={() => setActiveTab(tab)}
          >
            {tab === 'testdrives' ? 'Заявки' : tab === 'cars' ? 'Автомобили' : tab === 'users' ? 'Пользователи' : 'Дашборд'}
          </button>
        ))}
      </div>

      <div className={styles.content}>
        {/* ================= ДАШБОРД ================= */}
        {activeTab === 'dashboard' && stats && (
          <div className={styles.dashboard}>
            <div className={styles.statCard}><h3>Пользователи</h3><p>{stats.total_users}</p></div>
            <div className={styles.statCard}><h3>Автомобили</h3><p>{stats.total_cars}</p></div>
            <div className={styles.statCard}><h3>Заявки на тест-драйв</h3><p>{stats.total_testdrives}</p></div>
            <div className={styles.statCard}><h3>Покупки</h3><p>{stats.total_purchases}</p></div>
          </div>
        )}

        {/* ================= ПОЛЬЗОВАТЕЛИ ================= */}
        {activeTab === 'users' && (
          <div>
            <table className={styles.table}>
              <thead><tr><th>ID</th><th>Email</th><th>Имя</th><th>Роль</th><th>Действия</th></tr></thead>
              <tbody>
                {users.map(u => (
                  <tr key={u.id}>
                    <td>{u.id}</td><td>{u.email}</td><td>{u.full_name}</td>
                    <td>
                      <select value={u.role} onChange={(e) => handleRoleChange(u.id, e.target.value)} disabled={u.id === user.id}>
                        <option value="user">user</option>
                        <option value="admin">admin</option>
                      </select>
                    </td>
                    <td>
                      <button onClick={() => handleDeleteUser(u.id)} disabled={u.id === user.id || u.role === 'admin'} className={styles.deleteBtn}>Удалить</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* ================= АВТОМОБИЛИ ================= */}
        {activeTab === 'cars' && (
          <div>
            <button className={styles.addBtn} onClick={() => setShowAddForm(!showAddForm)}>
              {showAddForm ? 'Отменить' : 'Добавить автомобиль'}
            </button>

            {showAddForm && (
              <div className={styles.formWrapper}>
                <form onSubmit={handleAddCar} className={styles.addForm}>
                  <h4>Новый автомобиль</h4>

                  {/* Прокручиваемая часть полей */}
                  <div className={styles.formFields}>
                    <div className={styles.formRow}>
                      <div className={styles.formGroup}>
                        <label>Марка *</label>
                        <select value={newCar.brand} onChange={handleBrandChange} className={formErrors.brand ? styles.inputError : ''}>
                          <option value="">-- Выберите марку --</option>
                          {Object.keys(brandModels).map(brand => (
                            <option key={brand} value={brand}>{brand}</option>
                          ))}
                        </select>
                        {formErrors.brand && <span className={styles.errorMsg}>{formErrors.brand}</span>}
                      </div>

                      <div className={styles.formGroup}>
                        <label>Модель *</label>
                        <select value={newCar.model} onChange={handleModelChange} disabled={!newCar.brand} className={formErrors.model ? styles.inputError : ''}>
                          <option value="">-- Выберите модель --</option>
                          {availableModels.map(model => (
                            <option key={model} value={model}>{model}</option>
                          ))}
                        </select>
                        {formErrors.model && <span className={styles.errorMsg}>{formErrors.model}</span>}
                      </div>
                    </div>

                    <div className={styles.formRow}>
                      <div className={styles.formGroup}>
                        <label>Год выпуска *</label>
                        <input type="number" value={newCar.year} onChange={e => setNewCar({...newCar, year: e.target.value})} placeholder="Например, 2024" className={formErrors.year ? styles.inputError : ''} />
                        {formErrors.year && <span className={styles.errorMsg}>{formErrors.year}</span>}
                      </div>

                      <div className={styles.formGroup}>
                        <label>Цена (₽) *</label>
                        <input type="number" value={newCar.price} onChange={e => setNewCar({...newCar, price: e.target.value})} placeholder="Например, 15000000" className={formErrors.price ? styles.inputError : ''} />
                        {formErrors.price && <span className={styles.errorMsg}>{formErrors.price}</span>}
                      </div>
                    </div>

                    <div className={styles.formGroup}>
                      <label>Описание</label>
                      <textarea value={newCar.description} onChange={e => setNewCar({...newCar, description: e.target.value})} rows="2" placeholder="Краткое описание" />
                    </div>

                    <div className={styles.formRow}>
                      <div className={styles.formGroup}>
                        <label>Тип кузова</label>
                        <select value={newCar.body_type} onChange={e => setNewCar({...newCar, body_type: e.target.value})}>
                          {Object.entries(bodyTypesRussian).map(([key, label]) => (
                            <option key={key} value={key}>{label}</option>
                          ))}
                        </select>
                      </div>

                      <div className={styles.formGroup}>
                        <label>Рестайлинг</label>
                        <label className={styles.checkboxLabel}>
                          <input
                            type="checkbox"
                            checked={newCar.restyling}
                            onChange={e => setNewCar({...newCar, restyling: e.target.checked})}
                          />
                          Есть рестайлинг
                        </label>
                      </div>
                    </div>

                    <div className={styles.formRow}>
                      <div className={styles.formGroup}>
                        <label>Загрузить фото</label>
                        <input type="file" onChange={handleFileUpload} accept="image/*" />
                        {uploading && <span> Загрузка...</span>}
                      </div>
                      <div className={styles.formGroup}>
                        <label>Или укажите URL изображения</label>
                        <input type="text" value={newCar.image_url} onChange={e => setNewCar({...newCar, image_url: e.target.value})} placeholder="https://..." />
                      </div>
                    </div>

                    {addError && <div className={styles.serverError}>{addError}</div>}
                  </div>

                  {/* Фиксированная кнопка */}
                  <div className={styles.formActions}>
                    <button type="submit" className={styles.submitBtn}>Добавить автомобиль</button>
                  </div>
                </form>
              </div>
            )}

            <table className={styles.table}>
              <thead><tr><th>ID</th><th>Марка</th><th>Модель</th><th>Цена</th><th>Действия</th></tr></thead>
              <tbody>
                {cars.map(car => (
                  <tr key={car.id}>
                    <td>{car.id}</td><td>{car.brand}</td><td>{car.model}</td>
                    <td>{car.price.toLocaleString()} ₽</td>
                    <td>
                      <button className={styles.addBtn} style={{ marginRight: '0.5rem', padding: '0.4rem 1rem' }} onClick={() => openCarImages(car.id)}>Фото</button>
                      <button className={styles.deleteBtn} onClick={() => handleDeleteCar(car.id)}>Удалить</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            {selectedCarId && (
              <div className={styles.imagePanel}>
                <h3>Управление изображениями (авто ID: {selectedCarId})</h3>
                <div className={styles.imageControls}>
                  <input type="text" placeholder="URL изображения" value={newImageUrl} onChange={(e) => setNewImageUrl(e.target.value)} />
                  <button onClick={handleAddImage} className={styles.addBtn}>Добавить</button>
                </div>
                <div className={styles.imageGrid}>
                  {carImages.map(img => (
                    <div key={img.id} className={styles.thumbnailContainer}>
                      <img src={img.image_url} alt="" />
                      <button className={styles.deleteThumb} onClick={() => handleDeleteImage(img.id)}>×</button>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        )}

        {/* ================= ЗАЯВКИ ================= */}
        {activeTab === 'testdrives' && (
          <div>
            <table className={styles.table}>
              <thead><tr><th>ID</th><th>Пользователь</th><th>Авто ID</th><th>Дата</th><th>Статус</th></tr></thead>
              <tbody>
                {testDrives.map(td => (
                  <tr key={td.id}>
                    <td>{td.id}</td><td>{td.user_id}</td><td>{td.car_id}</td>
                    <td>{new Date(td.preferred_date).toLocaleString()}</td><td>{td.status}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>
    </motion.div>
  );
};

export default AdminPanel;
